#!/usr/bin/env node
import { readFileSync, writeFileSync, mkdirSync, existsSync, copyFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { TOOLING_ROOT, appDir } from './lib/workspace-root.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const HEADER =
  '/* GENERATED by capricorn-tooling/scripts/build-motion-tokens.mjs from shared/design-system/tokens.css — DO NOT EDIT. */';
const HEADER_TS =
  '// GENERATED by capricorn-tooling/scripts/build-motion-tokens.mjs from shared/design-system/tokens.css — DO NOT EDIT.';
const HEADER_DART =
  '// GENERATED by capricorn-tooling/scripts/build-motion-tokens.mjs from shared/design-system/tokens.css — DO NOT EDIT.';

const TOKENS_CSS = join(TOOLING_ROOT, 'shared/design-system/tokens.css');
const OUT_DIR = join(TOOLING_ROOT, 'shared/design-system/generated');
const TARGETS_JSON = join(__dirname, 'motion-targets.json');

const check = process.argv.includes('--check');
const sync = process.argv.includes('--sync');

function toCamel(s) {
  return s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

function parseTokens(css) {
  const durs = {};
  const eases = {};
  for (const m of css.matchAll(/--cap-dur-([\w-]+):\s*(\d+)ms\s*;/g)) {
    durs[toCamel(m[1])] = Number(m[2]);
  }
  for (const m of css.matchAll(/--cap-ease(?:-([\w-]+))?:\s*cubic-bezier\(\s*([^)]+)\s*\)\s*;/g)) {
    const key = m[1] ? toCamel(m[1]) : 'base';
    const nums = m[2].split(',').map((x) => Number(x.trim()));
    eases[key] = nums;
  }
  if (Object.keys(durs).length < 7 || Object.keys(eases).length < 3) {
    console.error(
      `motion token parse failed: ${Object.keys(durs).length} durations (need ≥7), ${Object.keys(eases).length} easings (need ≥3)`
    );
    process.exit(1);
  }
  return { durs, eases };
}

function buildOutputs({ durs, eases }) {
  const durCss = Object.entries(durs)
    .map(([k, ms]) => `  --cap-dur-${k.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}: ${ms}ms;`)
    .join('\n');
  const easeCss = Object.entries(eases)
    .map(([k, arr]) => {
      const varName = k === 'base' ? '--cap-ease' : `--cap-ease-${k.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}`;
      return `  ${varName}: cubic-bezier(${arr.join(', ')});`;
    })
    .join('\n');
  const capMotionTokensCss = `${HEADER}\n:root {\n${easeCss}\n${durCss}\n}\n`;

  const durLines = Object.entries(durs)
    .map(([k, ms]) => `  ${k}: ${ms}`)
    .join(',\n');
  const durSecLines = Object.entries(durs)
    .map(([k, ms]) => `  ${k}: ${ms / 1000}`)
    .join(',\n');
  const easeLines = Object.entries(eases)
    .map(([k, arr]) => `  ${k}: [${arr.join(', ')}]`)
    .join(',\n');
  const capMotionTs = `${HEADER_TS}\nexport const CapDur = {\n${durLines},\n} as const;\nexport const CapDurSec = {\n${durSecLines},\n} as const;\nexport const CapEase = {\n${easeLines},\n} as const;\nexport type CapDurKey = keyof typeof CapDur;\n`;

  const easeDartName = (k) => (k === 'base' ? 'ease' : `ease${k[0].toUpperCase()}${k.slice(1)}`);
  const durDart = Object.entries(durs)
    .map(([k, ms]) => `  static const Duration ${k} = Duration(milliseconds: ${ms});`)
    .join('\n');
  const easeDart = Object.entries(eases)
    .map(([k, arr]) => `  static const Cubic ${easeDartName(k)} = Cubic(${arr.join(', ')});`)
    .join('\n');
  const capMotionDart = `${HEADER_DART}\nimport "package:flutter/animation.dart";\n\nabstract class CapMotion {\n  CapMotion._();\n${durDart}\n${easeDart}\n}\n`;

  return {
    'cap-motion-tokens.css': capMotionTokensCss,
    'capMotion.ts': capMotionTs,
    'cap_motion.dart': capMotionDart,
  };
}

const css = readFileSync(TOKENS_CSS, 'utf8');
const outputs = buildOutputs(parseTokens(css));

function writeGenerated() {
  mkdirSync(OUT_DIR, { recursive: true });
  for (const [name, content] of Object.entries(outputs)) {
    writeFileSync(join(OUT_DIR, name), content);
  }
}

function runSync() {
  const { targets } = JSON.parse(readFileSync(TARGETS_JSON, 'utf8'));
  for (const { app, files } of targets) {
    const root = appDir(app);
    if (!existsSync(root)) {
      console.warn(`skip sync: app dir missing — ${root}`);
      continue;
    }
    for (const [genName, rel] of Object.entries(files)) {
      const dest = join(root, rel);
      mkdirSync(dirname(dest), { recursive: true });
      copyFileSync(join(OUT_DIR, genName), dest);
    }
  }
}

function runCheck() {
  const problems = [];
  for (const [name, content] of Object.entries(outputs)) {
    const p = join(OUT_DIR, name);
    if (!existsSync(p)) problems.push(`${p} (missing)`);
    else if (readFileSync(p, 'utf8') !== content) problems.push(`${p} (out of date)`);
  }
  const { targets } = JSON.parse(readFileSync(TARGETS_JSON, 'utf8'));
  for (const { app, files } of targets) {
    const root = appDir(app);
    if (!existsSync(root)) continue;
    for (const [genName, rel] of Object.entries(files)) {
      const dest = join(root, rel);
      const content = outputs[genName];
      if (!existsSync(dest)) problems.push(`${dest} (missing app copy)`);
      else if (readFileSync(dest, 'utf8') !== content) problems.push(`${dest} (out of date)`);
    }
  }
  if (problems.length) {
    console.error('build-motion-tokens --check failed:\n' + problems.map((x) => `  ${x}`).join('\n'));
    process.exit(1);
  }
  console.log('build-motion-tokens --check OK');
}

if (check) {
  runCheck();
} else {
  writeGenerated();
  if (sync) runSync();
  console.log('Wrote motion token outputs to shared/design-system/generated/');
}